topo_modhash_t * topo_modhash_create ( topo_hdl_t * thp ) { topo_modhash_t * mhp ; mhp -> mh_hashlen = TOPO_HASH_BUCKETS ; if ( ( mhp -> mh_hash = topo_hdl_zalloc ( thp , sizeof ( void * ) * mhp -> mh_hashlen ) ) == NULL ) { topo_hdl_free ( thp , mhp , sizeof ( topo_modhash_t ) ) ; return ( NULL ) ; } mhp -> mh_nelems = 0 ; ( void ) pthread_mutex_init ( & mhp -> mh_lock , NULL ) ; thp -> th_modhash = mhp ; return ( mhp ) ; } 